SELECT t.object_id, c.object_id AS main_match_id, m.object_id AS morphology_match_id, c.position_angle, c.position_angle_err, c.ellipticity, c.ellipticity_err, c.semimajor_axis, c.semimajor_axis_err, m.sersic_angle, m.sersic_angle_err, m.sersic_sersic_vis_axis_ratio, m.sersic_sersic_vis_axis_ratio_err, m.sersic_sersic_vis_radius, m.sersic_visnir_flags, m.disk_sersic_angle, m.disk_sersic_disk_axis_ratio, m.disk_sersic_flags, m.bar_strong, m.bar_weak, m.bar_no FROM TAP_UPLOAD.targets t LEFT OUTER JOIN catalogue.mer_catalogue c ON t.object_id=c.object_id LEFT OUTER JOIN catalogue.mer_morphology m ON t.object_id=m.object_id